(3959631, 562175, 23002, '<td valign="top">it would be much nicer if there were more distinction between the bear and the background.  if it was not for the basic editing, a nice selective desat would have worked well here.</td>', 'it would be much nicer if there were more distinction between the bear and the background.  if it was not for the basic editing, a nice selective desat would have worked well here.', '2007-08-01 23:34:24.000000', NULL, 1),
(3959632, 563659, 37930, '<td valign="top">Clever. Nice shot, too. Mid-flight dragonflies in focus has always been something I wanted to accomplish, which I have now, though nothing as nice as this. Problem with these is that they always want their back to the sun so their faces are always dark and difficult to see (with basic editing, anyways). Very good capture.</td>', 'Clever. Nice shot, too. Mid-flight dragonflies in focus has always been something I wanted to accomplish, which I have now, though nothing as nice as this. Problem with these is that they always want their back to the sun so their faces are always dark and difficult to see (with basic editing, anyways). Very good capture.', '2007-08-01 23:34:32.000000', NULL, 1),
(3959634, 562399, 15711, '<td valign="top">Now THAT is a photograph.  Beautifully done.  My fav so far. I thought I was sick of seascapes too. (hee hee hee)</td>', 'Now THAT is a photograph.  Beautifully done.  My fav so far. I thought I was sick of seascapes too. (hee hee hee)', '2007-08-01 23:34:49.000000', NULL, 1),
