(3959686, 564310, 37930, '<td valign="top">Neat idea, though the hand is a little dark and drab looking, and the bottom-right is a bit blown out.</td>', 'Neat idea, though the hand is a little dark and drab looking, and the bottom-right is a bit blown out.', '2007-08-01 23:45:47.000000', NULL, 1),
(3959687, 564307, 15711, '<td valign="top">Staged, but well executed. Sometimes the deliberate shots almost seem too forced, but this is cool.</td>', 'Staged, but well executed. Sometimes the deliberate shots almost seem too forced, but this is cool.', '2007-08-01 23:45:51.000000', NULL, 1),
(3959690, 564554, 33672, '<td valign="top">Great tones! nice take on the theme.</td>', 'Great tones! nice take on the theme.', '2007-08-01 23:46:33.000000', NULL, 1),
(3959692, 563659, 15711, '<td valign="top">That''s amazing stop action.  The bokeh is heavenly.  Nice shot.  Maybe a touch of a shoehorn into a Stones song, but I can go with it. ;~D</td>', 'That''s amazing stop action.  The bokeh is heavenly.  Nice shot.  Maybe a touch of a shoehorn into a Stones song, but I can go with it. ;~D', '2007-08-01 23:47:01.000000', NULL, 1),
