(3989871, 564158, 62318, '<td valign="top">Very serene and nice moody calm feeling. Terrific placement of elements in the frame. My only suggestion might be to crop some of the top off in order to remove the light at the top, so only the door and reflection are your light sources. Still a very nice capture. Congrats.</td>', 'Very serene and nice moody calm feeling. Terrific placement of elements in the frame. My only suggestion might be to crop some of the top off in order to remove the light at the top, so only the door and reflection are your light sources. Still a very nice capture. Congrats.', '2007-08-12 01:36:01.000000', NULL, 0),
(3989873, 564287, 62318, '<td valign="top">A splendid sunset shot. You have that sun at the perfect time on the horizon.</td>', 'A splendid sunset shot. You have that sun at the perfect time on the horizon.', '2007-08-12 01:37:33.000000', NULL, 0),
(3990419, 564412, 52336, '<td valign="top">What a beautiful photo.</td>', 'What a beautiful photo.', '2007-08-12 12:02:47.000000', NULL, 0),
